def transform(grid):
    counts = {2: 0, 3: 0}
    for row in grid:
        i = 0
        while i < len(row):
            c = row[i]
            if c in counts:
                counts[c] += 1
                while i < len(row) and row[i] == c:
                    i += 1
            else:
                i += 1
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
